[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Bestselling Books: Price vs. User Rating Trend Analysis (2009–2019)</title>
<style>
  :root {
    --bg: #f8f9fb;
    --card: #ffffff;
    --primary: #1a3a5c;
    --accent: #2e7dbe;
    --accent2: #e85d26;
    --accent3: #2caa6e;
    --muted: #6b7a8d;
    --border: #dde3ea;
    --text: #1e2733;
    --text-light: #4a5568;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; }

  /* Header */
  .report-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2e5f8a 60%, #1e4d7a 100%);
    color: #fff;
    padding: 48px 60px 40px;
    position: relative;
    overflow: hidden;
  }
  .report-header::after {
    content: '';
    position: absolute; right: -60px; top: -60px;
    width: 300px; height: 300px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }
  .report-header h1 { font-size: 2rem; font-weight: 700; letter-spacing: -0.5px; line-height: 1.25; max-width: 680px; }
  .report-header .subtitle { margin-top: 10px; font-size: 1rem; opacity: 0.8; }
  .report-header .meta { margin-top: 20px; font-size: 0.78rem; opacity: 0.6; text-transform: uppercase; letter-spacing: 0.08em; }

  /* Layout */
  .content { max-width: 1100px; margin: 0 auto; padding: 40px 32px; }
  .section { margin-bottom: 56px; }
  .section-title {
    font-size: 1.35rem; font-weight: 700; color: var(--primary);
    border-left: 4px solid var(--accent); padding-left: 14px;
    margin-bottom: 24px;
  }
  .section-intro { font-size: 0.95rem; color: var(--text-light); margin-bottom: 24px; max-width: 820px; }

  /* KPI Cards */
  .kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 16px; }
  .kpi-card {
    background: var(--card); border: 1px solid var(--border); border-radius: 10px;
    padding: 20px 18px; text-align: center;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  }
  .kpi-value { font-size: 1.9rem; font-weight: 800; color: var(--accent); line-height: 1; }
  .kpi-label { font-size: 0.78rem; color: var(--muted); margin-top: 6px; text-transform: uppercase; letter-spacing: 0.06em; }

  /* Two-col layout */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  @media(max-width:720px) { .two-col { grid-template-columns: 1fr; } }

  /* Cards */
  .card {
    background: var(--card); border: 1px solid var(--border); border-radius: 10px;
    padding: 24px; box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  }
  .card-title { font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin-bottom: 16px; }

  /* Tables */
  table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
  th { background: #f0f4f8; color: var(--primary); font-weight: 700; text-align: left; padding: 10px 14px; border-bottom: 2px solid var(--border); }
  td { padding: 9px 14px; border-bottom: 1px solid var(--border); }
  tr:last-child td { border-bottom: none; }
  tr:hover td { background: #f8fbff; }
  .num { text-align: right; font-variant-numeric: tabular-nums; }
  .badge-fiction { background: #dbeafe; color: #1e40af; border-radius: 4px; padding: 2px 7px; font-size: 0.75rem; font-weight: 600; }
  .badge-nonfiction { background: #dcfce7; color: #166534; border-radius: 4px; padding: 2px 7px; font-size: 0.75rem; font-weight: 600; }

  /* Correlation badge */
  .corr-badge {
    display: inline-flex; align-items: center; gap: 8px;
    background: #fff3e0; border: 1px solid #fbbf24;
    border-radius: 8px; padding: 12px 18px; margin-top: 12px;
    font-size: 0.95rem; font-weight: 600; color: #92400e;
  }
  .corr-value { font-size: 1.4rem; font-weight: 800; color: #b45309; }

  /* SVG Charts */
  .chart-wrap { width: 100%; overflow: hidden; }
  svg { display: block; width: 100%; }

  /* Insight callout */
  .insight {
    background: #eff6ff; border-left: 4px solid var(--accent);
    border-radius: 0 8px 8px 0; padding: 14px 18px;
    font-size: 0.9rem; color: #1e40af; margin-top: 16px;
  }
  .insight strong { color: #1a3a5c; }

  /* Recommendation cards */
  .rec-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
  .rec-card {
    background: var(--card); border: 1px solid var(--border); border-radius: 10px;
    padding: 20px; border-top: 4px solid var(--accent);
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  }
  .rec-card h4 { font-size: 0.95rem; font-weight: 700; color: var(--primary); margin-bottom: 8px; }
  .rec-card p { font-size: 0.875rem; color: var(--text-light); line-height: 1.55; }
  .rec-card .rec-source { font-size: 0.75rem; color: var(--muted); margin-top: 10px; font-style: italic; }

  /* Genre comparison summary table */
  .genre-compare-table th { font-size: 0.82rem; }
  .fiction-col { color: #1e40af; font-weight: 700; }
  .nonfic-col { color: #166534; font-weight: 700; }

  /* Inflection callout */
  .inflection-pill {
    display: inline-block;
    background: #fef3c7; color: #92400e;
    border: 1px solid #fbbf24;
    border-radius: 20px; padding: 3px 12px;
    font-size: 0.75rem; font-weight: 700;
    margin-left: 8px;
  }

  footer {
    text-align: center; padding: 32px; font-size: 0.78rem; color: var(--muted);
    border-top: 1px solid var(--border); margin-top: 20px;
  }
</style>
</head>
<body>

<!-- ─── HEADER ─── -->
<div class="report-header">
  <div class="meta">Trend Analysis Report &nbsp;|&nbsp; Management Edition &nbsp;|&nbsp; April 2026</div>
  <h1>Amazon Bestselling Books<br>Price vs. User Rating Trend Analysis</h1>
  <div class="subtitle">A data-driven examination of pricing strategy and customer satisfaction across Fiction &amp; Non-Fiction genres, 2009–2019</div>
</div>

<div class="content">

<!-- ─── SECTION 1: MARKET OVERVIEW ─── -->
<div class="section">
  <div class="section-title">1. Bestseller Market Overview (2009–2019)</div>
  <p class="section-intro">
    This report is based on Amazon's top-50 bestselling books for each year from 2009 through 2019 — 550 annual bestseller slots covering 351 unique titles across Fiction and Non Fiction. The dataset captures a decade of consumer preference, pricing evolution, and engagement volume, providing a statistically robust foundation for strategic analysis.
  </p>

  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-value">550</div>
      <div class="kpi-label">Total Records</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">351</div>
      <div class="kpi-label">Unique Titles</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">$13.10</div>
      <div class="kpi-label">Avg Book Price</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">4.62</div>
      <div class="kpi-label">Avg User Rating</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">11,953</div>
      <div class="kpi-label">Avg Reviews / Book</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">56%</div>
      <div class="kpi-label">Non Fiction Share</div>
    </div>
  </div>

  <div style="margin-top:24px;" class="card">
    <div class="card-title">Genre Distribution Across the Decade</div>
    <!-- Stacked bar chart: Fiction vs Non Fiction per year -->
    <div class="chart-wrap">
      <svg viewBox="0 0 860 200" xmlns="http://www.w3.org/2000/svg">
        <!-- Axes -->
        <line x1="70" y1="10" x2="70" y2="165" stroke="#dde3ea" stroke-width="1.5"/>
        <line x1="70" y1="165" x2="840" yyyyy1="165" stroke="#dde3ea" stroke-width="1.5"/>
        <!-- Y axis labels -->
        <text x="62" y="168" fill="#6b7a8d" font-size="11" text-anchor="end">0</text>
        <text x="62" y="127" fill="#6b7a8d" font-size="11" text-anchor="end">20</text>
        <text x="62" y="86" fill="#6b7a8d" font-size="11" text-anchor="end">40</text>
        <!-- Gridlines -->
        <line x1="70" y1="127" x2="840" y2="127" stroke="#eef1f5" stroke-width="1"/>
        <line x1="70" y1="86" x2="840" y2="86" stroke="#eef1f5" stroke-width="1"/>

        <!-- Scale: 50 books per year. Height 155px total → 1 book = 3.1px -->
        <!-- Year bars: x start=85, bar width=52, gap=20 -->
        <!-- Years: 2009..2019, fiction/non-fiction counts from data -->
        <!-- 2009: F=24, NF=26 -->
        <rect x="85" y="90.6" width="40" height="74.4" fill="#2e7dbe" opacity="0.85"/>
        <rect x="85" y="9.6" width="40" height="81.0" fill="#2caa6e" opacity="0.85"/>
        <text x="105" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2009</text>

        <!-- 2010: F=20, NF=30 -->
        <rect x="147" y="103.0" width="40" height="62.0" fill="#2e7dbe" opacity="0.85"/>
        <rect x="147" y="9.0" width="40" height="93.0" fill="#2caa6e" opacity="0.85"/>
        <text x="167" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2010</text>

        <!-- 2011: F=21, NF=29 -->
        <rect x="209" y="100.1" width="40" height="65.1" fill="#2e7dbe" opacity="0.85"/>
        <rect x="209" y="10.0" width="40" height="89.9" fill="#2caa6e" opacity="0.85"/>
        <text x="229" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2011</text>

        <!-- 2012: F=21, NF=29 -->
        <rect x="271" y="100.1" width="40" height="65.1" fill="#2e7dbe" opacity="0.85"/>
        <rect x="271" y="10.0" width="40" height="89.9" fill="#2caa6e" opacity="0.85"/>
        <text x="291" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2012</text>

        <!-- 2013: F=24, NF=26 -->
        <rect x="333" y="90.6" width="40" height="74.4" fill="#2e7dbe" opacity="0.85"/>
        <rect x="333" y="9.6" width="40" height="80.6" fill="#2caa6e" opacity="0.85"/>
        <text x="353" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2013</text>

        <!-- 2014: F=29, NF=21 -->
        <rect x="395" y="75.1" width="40" height="89.9" fill="#2e7dbe" opacity="0.85"/>
        <rect x="395" y="10.0" width="40" height="65.1" fill="#2caa6e" opacity="0.85"/>
        <text x="415" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2014</text>

        <!-- 2015: F=17, NF=33 -->
        <rect x="457" y="112.3" width="40" height="52.7" fill="#2e7dbe" opacity="0.85"/>
        <rect x="457" y="9.7" width="40" height="102.3" fill="#2caa6e" opacity="0.85"/>
        <text x="477" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2015</text>

        <!-- 2016: F=19, NF=31 -->
        <rect x="519" y="106.1" width="40" height="58.9" fill="#2e7dbe" opacity="0.85"/>
        <rect x="519" y="9.9" width="40" height="96.1" fill="#2caa6e" opacity="0.85"/>
        <text x="539" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2016</text>

        <!-- 2017: F=24, NF=26 -->
        <rect x="581" y="90.6" width="40" height="74.4" fill="#2e7dbe" opacity="0.85"/>
        <rect x="581" y="9.6" width="40" height="80.6" fill="#2caa6e" opacity="0.85"/>
        <text x="601" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2017</text>

        <!-- 2018: F=21, NF=29 -->
        <rect x="643" y="100.1" width="40" height="65.1" fill="#2e7dbe" opacity="0.85"/>
        <rect x="643" y="10.0" width="40" height="89.9" fill="#2caa6e" opacity="0.85"/>
        <text x="663" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2018</text>

        <!-- 2019: F=20, NF=30 -->
        <rect x="705" y="103.0" width="40" height="62.0" fill="#2e7dbe" opacity="0.85"/>
        <rect x="705" y="9.0" width="40" height="94.0" fill="#2caa6e" opacity="0.85"/>
        <text x="725" y="178" fill="#6b7a8d" font-size="10" text-anchor="middle">2019</text>

        <!-- Legend -->
        <rect x="790" y="20" width="12" height="12" fill="#2e7dbe" rx="2"/>
        <text x="806" y="30" fill="#4a5568" font-size="11">Fiction</text>
        <rect x="790" y="40" width="12" height="12" fill="#2caa6e" rx="2"/>
        <text x="806" y="50" fill="#4a5568" font-size="11">Non Fiction</text>
      </svg>
    </div>
    <div class="insight"><strong>Non Fiction dominates</strong> the bestseller list, representing 56% of all annual slots (310 of 550). The only exception was 2014, when Fiction titles edged ahead with 29 of 50 spots.</div>
  </div>
</div>

<!-- ─── SECTION 2: PRICE-RATING CORRELATION ─── -->
<div class="section">
  <div class="section-title">2. Price vs. User Rating: Correlation Analysis</div>
  <p class="section-intro">
    A core hypothesis for any retailer is that premium-priced titles signal higher quality, translating to better customer ratings. The data challenges this assumption directly.
  </p>

  <div class="two-col">
    <div class="card">
      <div class="card-title">Pearson Correlation: Price vs. Rating</div>
      <div class="corr-badge">
        <span>r =</span>
        <span class="corr-value">−0.133</span>
        <span style="font-size:0.82rem; font-weight:400; color:#78350f;">Weak negative relationship</span>
      </div>
      <p style="margin-top:16px; font-size:0.88rem; color:var(--text-light); line-height:1.6;">
        A Pearson coefficient of <strong>−0.133</strong> reveals a statistically weak negative correlation. Higher price does not predict higher satisfaction — if anything, modestly-priced books rate slightly better. The relationship is too weak to be a reliable pricing lever, but the directional signal is clear: <em>customers are not paying premiums for quality</em>.
      </p>
      <div class="insight" style="margin-top:16px;">
        <strong>Key takeaway:</strong> Price premium carries virtually no rating advantage. The bestseller market rewards content quality and cultural relevance over price point.
      </div>

      <div style="margin-top:24px;">
        <div class="card-title">Rating by Price Segment</div>
        <table>
          <thead>
            <tr><th>Price Range</th><th class="num">Books</th><th class="num">Avg Rating</th></tr>
          </thead>
          <tbody>
            <tr><td>$0 – $5</td><td class="num">87</td><td class="num"><strong>4.72</strong></td></tr>
            <tr><td>$6 – $10</td><td class="num">179</td><td class="num">4.65</td></tr>
            <tr><td>$11 – $15</td><td class="num">142</td><td class="num">4.58</td></tr>
            <tr><td>$16 – $20</td><td class="num">74</td><td class="num">4.50</td></tr>
            <tr><td>$21+</td><td class="num">68</td><td class="num">4.62</td></tr>
          </tbody>
        </table>
      </div>
    </div>

    <div class="card">
      <div class="card-title">Scatter: Price vs. User Rating (all 550 books)</div>
      <div class="chart-wrap">
        <!-- Scatter plot SVG: x=price (0-105), y=rating (3.3-4.9) -->
        <!-- viewBox: 360x300, margin: l=50, r=20, t=20, b=40 -->
        <svg viewBox="0 0 360 300" xmlns="http://www.w3.org/2000/svg">
          <!-- axes -->
          <line x1="50" y1="20" x2="50" y2="255" stroke="#dde3ea" stroke-width="1.5"/>
          <line x1="50" y1="255" x2="340" y2="255" stroke="#dde3ea" stroke-width="1.5"/>
          <!-- x gridlines & labels: 0,20,40,60,80,100 -->
          <!-- x scale: 50 + price*(290/105) -->
          <!-- y scale: 255 - (rating-3.3)*(235/1.6) -->
          <line x1="50" y1="255" x2="50" y2="258" stroke="#aaa" stroke-width="1"/>
          <text x="50" y="268" fill="#6b7a8d" font-size="9" text-anchor="middle">0</text>
